def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    MOD = 1_000_000_007
    if n == 0:
        return 1
    chars = list(dict.fromkeys(alphabet))
    nxt = [{}]
    fail = [0]
    bad = [False]
    for word in banned:
        node = 0
        for ch in word:
            if ch not in nxt[node]:
                nxt[node][ch] = len(nxt)
                nxt.append({})
                fail.append(0)
                bad.append(False)
            node = nxt[node][ch]
        bad[node] = True
    from collections import deque
    q = deque()
    for ch in chars:
        if ch in nxt[0]:
            child = nxt[0][ch]
            fail[child] = 0
            q.append(child)
        else:
            nxt[0][ch] = 0
    while q:
        node = q.popleft()
        bad[node] = bad[node] or bad[fail[node]]
        for ch in chars:
            if ch in nxt[node]:
                child = nxt[node][ch]
                fail[child] = nxt[fail[node]][ch]
                q.append(child)
            else:
                nxt[node][ch] = nxt[fail[node]][ch]
    ids = [i for i, flag in enumerate(bad) if not flag]
    index = {node: i for i, node in enumerate(ids)}
    size = len(ids)
    matrix = [[0] * size for _ in range(size)]
    for node in ids:
        row = index[node]
        for ch in chars:
            dest = nxt[node][ch]
            if not bad[dest]:
                matrix[row][index[dest]] += 1

    def multiply(a, b):
        result = [[0] * size for _ in range(size)]
        for i in range(size):
            for k in range(size):
                aik = a[i][k]
                if aik == 0:
                    continue
                bk = b[k]
                ri = result[i]
                for j in range(size):
                    ri[j] = (ri[j] + aik * bk[j]) % MOD
        return result

    result = [[1 if i == j else 0 for j in range(size)] for i in range(size)]
    base = matrix
    exp = n
    while exp:
        if exp & 1:
            result = multiply(result, base)
        base = multiply(base, base)
        exp >>= 1
    return sum(result[index[0]]) % MOD
